import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.server.ResponseStatusException;

@RestController
@RequestMapping("/api/people")
public class PersonController {

    public record PersonView(Long id, String name, Integer alpha, Integer beta, Integer gamma,
            Grade grade, Integer weight, Integer thrust, Integer drift, Integer momentum, Integer load, String tier, List<PatronView> patrons,
            Integer backing, Integer net, Integer rank, Integer percentile, LocalDate onset, Long age, Long decay, boolean active, Integer effective,
            Integer clout) {
        static PersonView of(Person p, Map<Long, Integer> ranks, LocalDate anchor) {
            Integer rank = ranks.get(p.getLocalId());
            return new PersonView(p.getLocalId(), p.getName(), p.getAlpha(), p.getBeta(), p.getGamma(),
                    p.getGrade(), p.getWeight(), p.getThrust(), p.getDrift(), p.getMomentum(), p.getLoad(), p.getTier(),
                    p.getPatrons().stream().map(o -> new PatronView(o.getLocalId(), o.getName())).toList(),
                    p.getBacking(), p.getNet(), rank, PersonController.percentile(rank, ranks.size()), p.getOnset(),
                    p.getAge(anchor), p.getDecay(anchor), p.isActive(), p.getEffective(), p.getClout());
        }
    }

    /**
     * A rank as a percentile of the ranked people: the best 100, the worst 0, evenly spread between
     * by rank and rounded to a whole number. A lone ranked person is 100; unranked has none.
     */
import java.util.Set;

/** A person on the list: a name and whole-number "alpha", "beta" and "gamma" (each absent until
 * given), and the derived "thrust" (alpha × beta), "drift" (gamma − alpha) and "momentum"
 * (thrust + 3 × drift), which are absent until all three raw values are given. A person may have
 * any number of "patrons": other people on the list, whose thrust added together is the person's
 * "backing". A person belongs to one sheet (null for the unnamed sheet) and is numbered within it, so sheets never share people. "Net" is momentum plus backing (backing counted as zero without patrons). A person may have a
 * "grade" (LOW, MID or HIGH; absent until given), from which their "weight" is 1, 3 or 5. "Load" is momentum times weight.
 * A person may have an "onset" date (absent until given); their "age" is the complete weeks from onset to the sheet's anchor.
 * "Decay" is momentum minus age. A person is "active" or not; a new person is active. "Clout" is the sum of the
 * patrons' effective (zero without patrons). */
@Entity
@Table(name = "person")
public class Person {

    @Id
            return momentum;
        }
        Integer backing = getBacking();
        return backing == null ? null : momentum + backing;
    }

    /** Effective is net while active, and half of net rounded down while not active (absent while net is). */
    public Integer getEffective() {
        Integer net = getNet();
        if (net == null || active) {
            return net;
        }
        return Math.floorDiv(net, 2);
    }

    /** Clout is the sum of the patrons' effective; zero without patrons, absent while any patron's effective is absent. */
    public Integer getClout() {
        int sum = 0;
        for (Person patron : patrons) {
            Integer effective = patron.getEffective();
            if (effective == null) {
                return null;
            }
            sum += effective;
        }
        return sum;
    }

    /** Tier classifies momentum: SINK below zero, STEADY up to 199, SURGE from 200; absent with momentum. */
    public String getTier() {
        Integer momentum = getMomentum();
        if (momentum == null) {
            return null;
        }
        return momentum < 0 ? "SINK" : momentum <= 199 ? "STEADY" : "SURGE";
    }
}
// 100 (the best) to 0 (the worst), rounded; a lone ranked person is 100.
// Each person may have a grade (LOW, MID or HIGH), chosen on add, in the edit form or on the row; their
// weight comes from it (LOW 1, MID 3, HIGH 5, "n/a" without a grade). Their load is momentum × weight
// ("n/a" while either is missing). The sheet's total load is everyone's load added together, leaving
// out anyone whose load is "n/a".
// The list shows one sheet: typing a sheet id and loading it opens that sheet, whose id is then
// shown, and people added belong to it. Until one is opened the unnamed sheet is shown. Opening an
// id no sheet has yet starts a new empty sheet with that id. Sheets are kept apart: each numbers
// its own people, and a sheet only ever shows (and edits) its own.
// The sheet shows its anchor date (today when none is set), and each person their onset date and
// their age: complete weeks from onset to the anchor, negative (toward zero) when onset is after it ("n/a" without onset).
// Their decay is momentum minus age ("n/a" while either is missing).
// Each person is active or not ("yes" or "no"; a new person is active), marked with the row's checkbox.
// Their effective is their net while active, and half their net rounded down while not active
// ("n/a" while net is).
// The sheet's active count is how many of its people are active, and its total effective is everyone's
// effective added together, leaving out anyone whose effective is "n/a".
// Their clout is their patrons' effective added together (zero without patrons; "n/a" while any
// patron's effective is "n/a").
@Component({
  selector: 'app-people',
  imports: [ReactiveFormsModule],
  template: `
    <h1>People</h1>

    <form (submit)="$event.preventDefault(); openSheet(sheetInput.value)" data-testid="sheet-form">
          <th scope="col">Momentum</th>
          <th scope="col">Load</th>
          <th scope="col">Tier</th>
          <th scope="col">Patrons</th>
          <th scope="col">Backing</th>
          <th scope="col">Net</th>
          <th scope="col">Effective</th>
          <th scope="col">Clout</th>
          <th scope="col">Rank</th>
          <th scope="col">Percentile</th>
          <th scope="col">Set alpha</th>
          <th scope="col">Set beta</th>
          <th scope="col">Set gamma</th>
          <th scope="col">Set grade</th>
          <th scope="col">Set active</th>
          <th scope="col">Set patrons</th>
          <th scope="col">Edit</th>
        </tr>
      </thead>
      <tbody>
        @for (p of people(); track p.id) {
          <tr [attr.data-testid]="'person-row-' + p.id">
            <td data-testid="person-name">{{ p.name }}</td>
            <td data-testid="person-alpha">{{ p.alpha }}</td>
            <td data-testid="person-beta">{{ p.beta }}</td>
            <td data-testid="person-gamma">{{ p.gamma }}</td>
            <td data-testid="person-grade">{{ p.grade }}</td>
            <td data-testid="person-active">{{ p.active ? 'yes' : 'no' }}</td>
            <td data-testid="person-onset">{{ p.onset }}</td>
            <td data-testid="concept-age">{{ p.age ?? 'n/a' }}</td>
            <td data-testid="concept-decay">{{ p.decay ?? 'n/a' }}</td>
            <td data-testid="concept-weight">{{ p.weight ?? 'n/a' }}</td>
            <td data-testid="concept-thrust">{{ p.thrust ?? 'n/a' }}</td>
            <td data-testid="concept-drift">{{ p.drift ?? 'n/a' }}</td>
            <td data-testid="concept-momentum">{{ p.momentum ?? 'n/a' }}</td>
            <td data-testid="concept-load">{{ p.load ?? 'n/a' }}</td>
            <td data-testid="concept-tier">{{ p.tier ?? 'n/a' }}</td>
            <td data-testid="person-patrons">{{ patronNames(p) }}</td>
            <td data-testid="concept-backing">{{ p.backing ?? 'n/a' }}</td>
            <td data-testid="concept-net">{{ p.net ?? 'n/a' }}</td>
            <td data-testid="concept-effective">{{ p.effective ?? 'n/a' }}</td>
            <td data-testid="concept-clout">{{ p.clout ?? 'n/a' }}</td>
            <td data-testid="concept-rank">{{ p.rank ?? 'n/a' }}</td>
            <td data-testid="concept-percentile">{{ p.percentile ?? 'n/a' }}</td>
            <td>
              <form (submit)="$event.preventDefault(); setAlpha(p, alphaInput.value)">
                <label class="visually-hidden" [for]="'person-alpha-edit-' + p.id">
                  Alpha for {{ p.name }}
                </label>
                <input
                  #alphaInput
  net: number | null;
  rank: number | null;
  percentile: number | null;
  onset: string | null;
  age: number | null;
  decay: number | null;
  active: boolean;
  effective: number | null;
  clout: number | null;
}

// A sheet: its id (null for the unnamed sheet) and its anchor date (yyyy-mm-dd; today when none is set).
export interface Sheet {

